<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])){header('Location: login.php');exit;} if(($_SESSION['user']['rol']??'')!=='superadmin'){header('Location: tienda-panel.php');exit;} $user=$_SESSION['user']; $config=require __DIR__.'/config.php'; $stores=[]; $products=[]; try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$stores=$pdo->query("SELECT id,nombre FROM tiendas WHERE estado='activa' ORDER BY nombre")->fetchAll();$products=$pdo->query('SELECT p.id,p.nombre,p.precio,p.estado,t.nombre AS tienda_nombre FROM productos p JOIN tiendas t ON t.id=p.tienda_id ORDER BY p.id DESC LIMIT 50')->fetchAll();}catch(Throwable $e){} function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');} ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0}main{max-width:900px;margin:auto;padding:40px 20px}.card{background:#fff;padding:24px;border-radius:16px;margin:16px 0}a{color:#886c42}label{display:block;margin:10px 0 4px}input,select,textarea{box-sizing:border-box;width:100%;padding:9px;border:1px solid #ccc;border-radius:7px}button{margin-top:14px;background:#886c42;color:#fff;border:0;padding:11px 17px;border-radius:8px}.product{border-top:1px solid #ddd;padding:12px 0}</style></head><body><main><p><a href="/">← Galería</a> · <a href="logout.php">Cerrar sesión</a></p><section class="card"><h1>Panel de <?=h($user['nombre'])?></h1><p>Rol: <?=h($user['rol'])?></p></section><section class="card"><h2>Tiendas</h2><p><a href="tiendas-admin.php">Administrar tiendas de la galería →</a></p></section><section class="card"><h2>Pedidos</h2><p><a href="pedidos-admin.php">Gestionar pedidos y estados de envío →</a></p></section><section class="card"><h2>Nuevo producto</h2><form method="post" action="producto-guardar.php"><label>Tienda</label><select name="tienda_id" required><?php foreach($stores as $store): ?><option value="<?=$store['id']?>"><?=h($store['nombre'])?></option><?php endforeach; ?></select><label>Nombre</label><input name="nombre" required maxlength="200"><label>Descripción</label><textarea name="descripcion"></textarea><label>Precio</label><input type="number" name="precio" min="0" step="0.01" required><button>Guardar producto</button></form></section><section class="card"><h2>Productos publicados</h2><?php foreach($products as $product): ?><div class="product"><strong><?=h($product['nombre'])?></strong> · S/ <?=h((string)$product['precio'])?> · <?=h($product['tienda_nombre'])?></div><?php endforeach; if(!$products): ?><p>No hay productos.</p><?php endif; ?></section></main></body></html>



